// ** Redux Imports
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit'

// ** UseJWT import to get config
import useJwt from '@src/auth/jwt/useJwt'

import axios from 'axios'

const config = useJwt.jwtConfig

const initialUser = () => {
  const item = window.localStorage.getItem('userData')
  //** Parse stored json or if none return initialValue
  return item ? JSON.parse(item) : {}
}

export const getMe = createAsyncThunk('appUser/me', async () => {
  const response = await axios.get('/api/v1/user/me')
  return response.data
})

export const updateMe = createAsyncThunk('appUser/me/update', async (me, { dispatch }) => {
  await axios.patch('/api/v1/user/me', me)
  await dispatch(getMe())
})

export const updateAvt = createAsyncThunk('appUser/me/update', async (avt, { dispatch }) => {
  await axios.post('/api/v1/user/update-avatar', avt)
  await dispatch(getMe())
})

export const authSlice = createSlice({
  name: 'authentication',
  initialState: {
    userData: initialUser()
  },
  reducers: {
    handleLogin: (state, action) => {
      // const {navigate} = action.payload
      state[config.storageTokenKeyName] = action.payload[config.storageTokenKeyName]
      // state[config.storageRefreshTokenKeyName] = action.payload[config.storageRefreshTokenKeyName]
      // navigate(getHomeRouteForLoggedInUser('admin'))
      // localStorage.setItem('userData', JSON.stringify(getMe()))
      localStorage.setItem(config.storageTokenKeyName, JSON.stringify(action.payload.accessToken))
      // localStorage.setItem(config.storageRefreshTokenKeyName, JSON.stringify(action.payload.refreshToken))
    },
    handleLogout: state => {
      state.userData = {}
      state[config.storageTokenKeyName] = null
      state[config.storageRefreshTokenKeyName] = null
      // ** Remove user, accessToken & refreshToken from localStorage
      localStorage.removeItem('userData')
      localStorage.removeItem(config.storageTokenKeyName)
      localStorage.removeItem(config.storageRefreshTokenKeyName)
    }
  },
  extraReducers: builder => {
    builder
      .addCase(getMe.fulfilled, (state, action) => {
        const adminAbility = [{action: 'manage', subject: 'all'}]
        // console.log(action.payload)
        state.userData = action.payload
        localStorage.setItem('userData', JSON.stringify({...action.payload, ability: adminAbility}))
      })
  }
})

export const { handleLogin, handleLogout } = authSlice.actions

export default authSlice.reducer
