// ** Redux Imports
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'
import useJwt from '@src/auth/jwt/useJwt'
import { closeSwal, handleLoading, handleWarning, toastSuccess } from '../../../sweetalert'
// ** Axios Imports
// import axios from 'axios'

export const getData = createAsyncThunk('tableDistribution/getData', async params => {
  try {
    const {showLoading} = params
    showLoading(true)
    const response = await useJwt.getListDistribution(params)
    console.log(response.data)
    const data = response.data.data
    const result = []
    const promises = data.map(async (item) => {
      console.log(item.updated_by)
      const user = await useJwt.getUserById(item.updated_by)
      result.push({
        ...item,
        userName: user.data.name
      })
    })
    await Promise.all(promises)
    console.log('perPage', response.data.page_size)
    showLoading(false)
    return { allData: result, data: result, totalPages: response.data.page_total, perPage: response.data.page_size, page: response.data.page, params }
    
  } catch (error) {
    showLoading(false)
    return {}
  }
})

export const deleteDistribution = createAsyncThunk('tableDistribution/deleteRow', async (params) => {
  try {
    handleLoading('Vui lòng chờ hệ thống...')
    await useJwt.deleteDistribution(params)
    await params.reloadTable()
    closeSwal()
    toastSuccess("Xóa thành công")
  } catch (error) {
    console.log(error)
    handleWarning('Cảnh báo', 'Kênh phân phối xóa không thành công.')
  }
})

export const deleteDistributions = createAsyncThunk('tableDistribution/deleteRows', async (params) => {
  try {
    handleLoading('Vui lòng chờ hệ thống...')
    const query = params.data.map(async (item) => {
      await useJwt.deleteDistribution({
        id: item.id
      })
      
    })
    await Promise.all(query)
    await params.reloadTable()
    closeSwal()
    toastSuccess("Xóa các kênh phân phối thành công")
  } catch (error) {
    console.log(error)
    handleWarning('Cảnh báo', 'Kênh phân phối xóa không thành công.')
  }
})
export const tableDistributionSlice = createSlice({
  name: 'tableDistribution',
  initialState: {
    data: [],
    total: 0,
    params: {},
    allData: [],
    isShowLoading: true,
    page: 1,
    perPage: 0,
    q: ''
  },
  reducers: {
    updateShowLoading: (state, action) => {
      state.isShowLoading = action.payload
    },
    updateSearch: (state, action) => {
      state.q = action.payload
    }
  },
  extraReducers: builder => {
    builder.addCase(getData.fulfilled, (state, action) => {
      state.data = action.payload.data
      state.params = action.payload.params
      state.allData = action.payload.allData
      state.total = action.payload.totalPages
      state.page = action.payload.page
      state.perPage = action.payload.perPage
    })
  }
})


export const reloadTable = createAsyncThunk("tableDistribution/reloadTable", async (params, { getState }) => {
  const state = getState().tableDistribution
  await params.getData(state.params)
})

export default tableDistributionSlice.reducer

export const {updateShowLoading, updateSearch}  = tableDistributionSlice.actions
