// ** Redux Imports
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'
import useJwt from '@src/auth/jwt/useJwt'
import { closeSwal, handleLoading, handleWarning, toastSuccess } from '../../../sweetalert'

export const getData = createAsyncThunk('datatablesCampaign/getData', async params => {
  try {
    console.log("ok")
    const response = await useJwt.getCampaign(params)
    return { error: null, allData: response.data.data, data: response.data.data, totalPages: response.data.page_total, params }
  } catch (error) {
    console.log(error)
    return { error, allData: [], data: [], totalPages: 1, params }
  }
})

export const datatablesCampaignSlice = createSlice({
  name: 'datatablesCampaign',
  initialState: {
    data: [],
    total: 1,
    params: {},
    allData: []
  },
  reducers: {},
  extraReducers: builder => {
    builder.addCase(getData.fulfilled, (state, action) => {
      state.data = action.payload.data
      state.params = action.payload.params
      state.allData = action.payload.allData
      state.total = action.payload.totalPages
    })
  }
})

export const deleteCampaign = createAsyncThunk('datatablesCampaign/deleteCampaign', async (params) => {
  try {
    handleLoading("Vui lòng chờ hệ thống...")
    await useJwt.deleteCampaign(params)
    await params.reloadTable()
    closeSwal()
    toastSuccess("Xóa thành công")
  } catch (error) {
    handleWarning("Cảnh báo", "Xóa chiến dịch không thành công. <br/>Vui lòng kiểm tra lại.")
  }
})

export const deleteCampaigns = createAsyncThunk('formAddCampaign/deleteCampaign', async (params) => {
  try {
    handleLoading("Vui lòng chờ hệ thống...")
    const query = params.data.map(async (item) => {
      await useJwt.deleteCampaign({
        id: item.id
      })
    })
    await Promise.all(query)
    await params.reloadTable()
    closeSwal()
    toastSuccess("Xóa các chiến dịch thành công")
    
  } catch (error) {
    closeSwal()
    handleWarning("Cảnh báo", "Xóa các chiến dịch không thành công.")
  }
})

export const updatedCampaignInfoWithStatus = createAsyncThunk('datatablesCampaign/updateStatus', async (params) => {
  try {
    await useJwt.updateCampaignInfoWithStatus({
      id: params.id,
      name: params.name,
      description: params.description,
      status: params.status,
      start_date: params.dateStart,
      end_date: params.dateEnd
    })
    await params.reloadTable()
    closeSwal()
    toastSuccess("Cập nhật thành công")
  } catch (error) {
    handleWarning("Cảnh báo", "Cập nhật trạng thái chiến dịch không thành công. <br/>Vui lòng kiểm tra lại.")
  }
})

export const reloadTable = createAsyncThunk('datatablesCampaign/deleteCampaign', async (params, {getState}) => {
  const store = getState().datatablesCampaign
  await params.getData(store.params)
})
export default datatablesCampaignSlice.reducer
