import { createAsyncThunk, createSlice } from "@reduxjs/toolkit"
import useJwt from '@src/auth/jwt/useJwt'

export const getData = createAsyncThunk('formShowCampaign/getData', async (params) => {
  const response = await useJwt.getCampaignWithID(params)
  const customers = await useJwt.getCustomersWithCampaignID(params)
  const arrCodeUsed = await useJwt.getRewardLinksUsedWithCampaignID(params)
  const arrCodeNotUsed = await useJwt.getRewardLinksNotUsedWithCampaignID(params)

  const arrToGetData = response.data.rewards.filter(item => item.start_percentage !== null)
  const percent = (arrToGetData.length > 0) ? arrToGetData[0].start_percentage * 100 : 0

  const rewardSorted = response.data.rewards
  for (let i = 0; i < rewardSorted.length - 1; i++) for (let j = i + 1; j < rewardSorted.length; j++) {
      if (rewardSorted[i].id > rewardSorted[j].id) {
        const tmp = rewardSorted[i]
        rewardSorted[i] = rewardSorted[j]
        rewardSorted[j] = tmp
      }
    }
    
  console.log(customers.data)
  return {
    campaignInfo: {
      name: response.data.name,
      startDate: response.data.start_date,
      endDate: response.data.end_date,
      description: response.data.description
    },
    coverCampaign: response.data.resources,
    coverRotation: response.data.wheel_images,
    agencies: response.data.agencies,
    rewards: rewardSorted,
    customers: customers.data.data,
    percent,
    specAwards: arrToGetData.map(item => ({
      value: item.name,
      label: item.name
    })),
    arrCodeUsed: arrCodeUsed.data.data,
    arrCodeNotUsed: arrCodeNotUsed.data.data
  }
})

const formShowCampaignSlice = createSlice({
  name: 'formShowCampaign',
  initialState: {
    campaignInfo: {},
    coverCampaign: [],
    coverRotation: [],
    agencies: [],
    rewards: [],
    customers: [],
    rewardLinks: [],
    percent: '',
    specAwards: [],
    arrCodeUsed: [],
    arrCodeNotUsed:[]
  },
  reducers: {
    setCampaignInfo: (state, action) => {
      return {
        ...state,
        campaignInfo: {
          ...action.payload.campaignInfo
        }
      }
    },
    setCoverCampaign: (state, action) => {
      return {
        ...state,
        coverCampaign: [...action.payload.coverCampaign]
      }
    },
    setCoverRotation: (state, action) => {
      return {
        ...state,
        coverRotation: action.payload.coverRotation
      }
    },
    setAgencies: (state, action) => {
      return {
        ...state,
        agencies: [...action.payload.agencies]
      }
    },
    setRewards: (state, action) => {
      return {
        ...state,
        rewards: [action.payload.rewards]
      }
    },
    setCustomers: (state, action) => {
      return {
        ...state,
        customers: [...action.payload.customers]
      }
    },
    setRewardLinks: (state, action) => {
      return {
        ...state,
        rewardLinks: [...action.payload.rewardLinks]
      }
    }
  },
  extraReducers: builder => {
    builder.addCase(getData.fulfilled, (state, action) => {
      return {
        ...state,
        campaignInfo: {
          ...state.campaignInfo,
          ...action.payload.campaignInfo 
        },
        coverCampaign: [...action.payload.coverCampaign],
        coverRotation: [...action.payload.coverRotation],
        agencies: [...action.payload.agencies],
        rewards: [...action.payload.rewards],
        customers: [...action.payload.customers],
        percent: action.payload.percent,
        specAwards: [...action.payload.specAwards],
        arrCodeUsed: [...action.payload.arrCodeUsed],
        arrCodeNotUsed: [...action.payload.arrCodeNotUsed]
      }
    })
  }
})

export default formShowCampaignSlice.reducer
export const {setCampaignInfo, setCoverCampaign, setCoverRotation, setAgencies,
              setRewards, setCustomers, setRewardLinks} = formShowCampaignSlice.actions