import { createAsyncThunk, createSlice } from "@reduxjs/toolkit"
import useJwt from '@src/auth/jwt/useJwt'
// import jwtDefaultConfig from '@src/@core/auth/jwt/jwtDefaultConfig.js'
import { closeSwal, handleLoading, handleWarning, toastSuccess } from '../../../sweetalert'

export const getAgencies = createAsyncThunk('formEditCampaign/getAgencies', async () => {
  try {
    const response = await useJwt.getListAgencyNoParams()
    return {listAgencies: response.data.data}
  } catch (error) {
    return {listAgencies: []}
  }

})

export const getData = createAsyncThunk('formEditCampaign/getData', async (params) => {
  try {
    const response = await useJwt.getCampaignWithID(params)
    const customers = await useJwt.getCustomersWithCampaignID(params)
    
    // console.log(customers.data)
    // const container = new DataTransfer()
    // const filesCoverCampaign = response.data.resources.map(async (resource, index) => {
    //   console.log(resource.file_path)
    //   const imgBlob = await useJwt.getImgURL(`${resource.file_path}`)
    //   const fileName = `${index}.jpg`
    //   const file = new File([imgBlob], fileName, {type:"image/jpeg", lastModified:new Date().getTime()}, 'utf-8')
    //   container.items.add(file)
    //   // try {
    //   // } catch (error) {
    //   // }
    // })
    // await Promise.all(filesCoverCampaign)
    // console.log("container", container.files)
    // console.log("coverRotaion", response.data.wheel_image)
    const arrToGetData = response.data.rewards.filter(item => item.start_percentage !== null)
    const percent = (arrToGetData.length > 0) ? arrToGetData[0].start_percentage * 100 : 0

    const rewardSorted = response.data.rewards
    for (let i = 0; i < rewardSorted.length - 1; i++) for (let j = i + 1; j < rewardSorted.length; j++) {
      if (rewardSorted[i].id > rewardSorted[j].id) {
        const tmp = rewardSorted[i]
        rewardSorted[i] = rewardSorted[j]
        rewardSorted[j] = tmp
      }
    }

    return {
      campaignInfo: {
        id: params.id,
        name: response.data.name,
        status: response.data.campaign_status_id,
        startDate: new Date(response.data.start_date),
        endDate: new Date(response.data.end_date),
        description: response.data.description
      },
      
      coverCampaignsBasic: response.data.resources,
      coverRotationBasic: response.data.wheel_images,
      agenciesBasic: response.data.agencies,
      rewardsBasic: rewardSorted,
      customers: customers.data.data,
      percent,
      specAwards: arrToGetData.map(item => ({
        value: item.name,
        label: item.name
      }))
    }
  } catch (error) {
    handleWarning("Cảnh báo", "Chỉnh sửa chiến dịch không thành công.")
  }
})

export const updateCampaign = createAsyncThunk('formEditCampaign/EditCampaign', async (params, {getState}) => {
  let id = 0
  try {
    const store = getState().formEditCampaign
    handleLoading("Vui lòng chờ hệ thống...")
    console.log(store)
    // GD1: Sửa thông tin chung
    const response = await useJwt.updateCampaignInfo(store)
    id = response.data.id
    // GD2: Sửa thông tin ảnh chiến dịch và ảnh vòng quay
    if (store.coverCampaigns.length > 0 || store.coverRotation.length > 0) {
      const response_2 = await useJwt.addCoverAndWheel({
        id: response.data.id,
        coverCampaigns: store.coverCampaigns,
        coverRotation: store.coverRotation
      })
      console.log(response_2)
    }
    // GD3: Sửa thông tin giải thưởng
    const resource_ids = []
    const requestArr = []
    const request = store.rewards.map(async (item) => {
      if (item.file === undefined || item.file === null || item.file.length === 0) {
        resource_ids.push((item.fileCurrent !== null && item.fileCurrent.length > 0) ? item.fileCurrent[0].id : -199)
      } else {
        const res_resource = await useJwt.updateResources({
          file: [...item.file]
        })
        resource_ids.push(res_resource.data[0].id)
      }
      requestArr.push(
        {
          name: item.name,
          total_amount: item.total_number,
          type: "string",
          color: "string",
          description: item.description,
          resource_ids: [resource_ids[resource_ids.length - 1]]
        }
      )
    })

    await Promise.all(request)
    console.log("pass", 
      {
        id,
        requestArr
      }
    )
    await useJwt.updateReward({
      id,
      requestArr
    })
    
    await useJwt.addCampaignAgencies({
      id: response.data.id,
      agencies: store.agencies
    })

    const responseData = await useJwt.getCampaignWithID({id})
    const dataServers = responseData.data.rewards
    const arr = []
    store.specAwards.map(reward => {
      dataServers.map(dataServer => {
        if (reward.value === dataServer.name) {
          arr.push(dataServer.id)
        }
      })
    })

    // console.log("Arr", {
    //   id,
    //   percent: store.percent,
    //   data: arr
    // })

    await useJwt.updateSpecicalAwards({
      id,
      percent: store.percent / 100.0,
      data: arr
    })

    closeSwal()
    toastSuccess("Chỉnh sửa thành công")
    return {
      id: "",
      status: "",
      name: null,
      dateStart: new Date(),
      dateEnd: new Date(),
      description: null,
      coverCampaigns: [],
      coverCampaignsBasic: [],
      coverRotation: [],
      coverRotationBasic: [],
  
      listAgencies: [],
      agencies: [
      {
        id: '',
        total_number: ''
      }
      ],
      agenciesBasic: [],
      rewards: [
        {
          name: '',
          total_number: '',
          description: '',
          file: ''
        }
      ],
      rewardsBasic: [],
      percent: '',
      specAwards: []
    }
    // console.log(response, response_2)
  } catch (error) {
    // await useJwt.deleteCampaign({
    //   id
    // })
    handleWarning("Cảnh báo", `Chỉnh sửa chiến dịch không thành công.`)
    return {
      id: "",
      status: "",
      name: null,
      dateStart: new Date(),
      dateEnd: new Date(),
      description: null,
      coverCampaigns: [],
      coverCampaignsBasic: [],
      coverRotation: [],
      coverRotationBasic: [],
  
      listAgencies: [],
      agencies: [
      {
        id: '',
        total_number: ''
      }
      ],
      agenciesBasic: [],
      rewards: [
        {
          name: '',
          total_number: '',
          description: '',
          file: ''
        }
      ],
      rewardsBasic: [],
      percent: '',
      specAwards: []
    }
  }
})

export const formEditCampainSlice = createSlice({
  name: 'formEditCampaign',
  initialState: {
    id: "",
    name: null,
    status: "",
    dateStart: new Date(),
    dateEnd: new Date(),
    description: null,

    coverCampaigns: [],
    coverCampaignsBasic: [],
    coverRotation: [],
    coverRotationBasic: [],

    listAgencies: [],
    agencies: [
    {
      id: '',
      total_number: ''
    }
    ],
    agenciesBasic: [],
    rewards: [
      {
        name: '',
        total_number: '',
        description: '',
        file: ''
      }
    ],
    rewardsBasic: [],
    percent: '',
    specAwards: []
  },
  reducers: {
    setName: (state, action) => {
      state.name = action.payload
    },
    setDateStart: (state, action) => {
      state.dateStart = action.payload
    },
    setDateEnd: (state, action) => {
      state.dateEnd = action.payload
    },
    setDescription: (state, action) => {
      state.description = action.payload
    },
    setCoverCampaigns: (state, action) => {
      return {
        ...state,
        coverCampaigns: [...action.payload.coverCampaigns]
      }
    },
    setCoverRotation: (state, action) => {
      state.coverRotation = action.payload.coverRotations
    },
    setAgencies: (state, action) => {
      // console.log('redux', action.payload.agencies)
      // state.agencies = action.payload.agencies
      return {
        ...state,
        agencies: [...action.payload.agencies]
      }
    },
    setRewards: (state, action) => {
      console.log(action.payload.rewards)
      return {
        ...state,
        rewards: [...action.payload.rewards]
      }
    },
    setPercent: (state, action) => {
      return {
        ...state,
        percent: action.payload.percent
      }
    },
    setSpecAwards: (state, action) => {
      return {
        ...state,
        specAwards: action.payload.specAwards
      }
    }
  },
  extraReducers: builder => {
    builder.addCase(getAgencies.fulfilled, (state, action) => {
      state.listAgencies = action.payload.listAgencies
    })
    .addCase(getData.fulfilled, (state, action) => {
      state.id = action.payload.campaignInfo.id
      state.name = action.payload.campaignInfo.name
      state.status = action.payload.campaignInfo.status
      state.dateStart = action.payload.campaignInfo.startDate
      state.dateEnd = action.payload.campaignInfo.endDate
      state.description = action.payload.campaignInfo.description
      state.coverCampaignsBasic = [...action.payload.coverCampaignsBasic]
      state.coverRotationBasic = [...action.payload.coverRotationBasic]
      state.agenciesBasic = [...action.payload.agenciesBasic]
      state.rewardsBasic = [...action.payload.rewardsBasic]
      state.percent = action.payload.percent
      state.specAwards = [...action.payload.specAwards]
    })
    .addCase(updateCampaign.fulfilled, (state, action) => {
      return {
        ...state,
        ...action.payload
      }
    })
  }
})

export default formEditCampainSlice.reducer

export const {setName, setDateStart, setDateEnd, setDescription, setCoverCampaigns,
              setCoverRotation, setAgencies, setRewards, setPercent, setSpecAwards} = formEditCampainSlice.actions