// ** Auth Endpoints
export default {
  // endPoint: 'https://quayso-be.tisoha.com',
  endPoint: 'https://quayso-api.vhngroup.vn',
  // endPoint: 'https://bfaa-113-172-232-92.ap.ngrok.io',
  // endPointLottery: 'https://vhn-quayso.tisoha.com/',
  endPointLottery: 'https://quayso.vhngroup.vn/',
  // loginEndpoint: `https://quayso-be.tisoha.com/api/v1/auth/jwt/login`,
  loginEndpoint: `https://quayso-api.vhngroup.vn/api/v1/auth/jwt/login`,
  registerEndpoint: '/api/v1/auth/jwt/register',
  refreshEndpoint: '/jwt/refresh-token',
  logoutEndpoint: '/jwt/logout',

  addDistributionEndpoint: '/api/v1/distributor_channels',
  getListDistributionsEndpoint: '/api/v1/distributor_channels',
  updateDistributionEndpoint: '/api/v1/distributor_channels',
  deleteDistributionEndpoint: '/api/v1/distributor_channels',

  addAgencyEndpoint: '/api/v1/agencies/user-id',
  addAgencyWithOwnerEndpoint: '/api/v1/agencies',
  editAgencyEndpoint: '/api/v1/agencies',
  checkIdAgencyEndpoint: '/api/v1/agencies',
  getAgenciesEndpoint: '/api/v1/agencies',
  deleteAgencyEndpoint: '/api/v1/agencies/',

  getCampaignInfoEndpoint: '/api/v1/campaigns',
  addCampaignInfoEndpoint: '/api/v1/campaigns',
  addCampaignResourcesEndpoint: (id) => `/api/v1/campaigns/${id}/resources`,
  addCampaignAgenciesEndpoint: (id) => `/api/v1/campaigns/${id}/agencies`,
  addCampaignRewardEndpoint: (id, name, total, description) => `/api/v1/campaigns/${id}/reward?name=${name}&description=${description}&total_amount=${total}`,
  deleteCampaignEndpoint: `/api/v1/campaigns`,
  getCampaignWithID: (id) => `/api/v1/campaigns/${id}`,
  getCustomerWithCampaignID: (id) => `/api/v1/reward-links?skip=0&limit=2000000000&order_by=id%20DESC&entity=campaign&entity_id=${id}&used=true&expand_agency=true&expand_reward=true`,
  getRewardLinksUsedWithCampaignID: (id) => `/api/v1/reward-links?skip=0&limit=2000000000&order_by=id%20DESC&entity=campaign&entity_id=${id}&used=true&&expand_agency=true`,
  getRewardLinksNotUsedWithCampaignID: (id) => `/api/v1/reward-links?skip=0&limit=2000000000&order_by=id%20DESC&entity=campaign&entity_id=${id}&used=false&&expand_agency=true`,
  updateCampaignInfoEndpoint: (campaign_id) => `/api/v1/campaigns/${campaign_id}`,
  updateRewardEndpoint: (campaign_id) => `/api/v1/campaigns/${campaign_id}/reward`,
  updateResourcesEndpoint: `/api/v1/resources`,
  updateSpecAwards: (campaign_id, percent) => `/api/v1/campaigns/${campaign_id}/reward_percentage?percentage=${percent}`,

  getSocialLinksEndPoint: '/api/v1/socials',
  updateSocialLinksEndPoint: (id) =>  `/api/v1/socials/${id}`,

  getAgencyCampaignWithACID: (id) => `/api/v1/agency-campaigns/${id}`,
  getUserById: '/api/v1/user/user',
  // ** This will be prefixed in authorization header with token
  // ? e.g. Authorization: Bearer <token>
  tokenType: 'Bearer',

  // ** Value of this property will be used as key to store JWT token in storage
  storageTokenKeyName: 'accessToken',
  storageRefreshTokenKeyName: 'refreshToken'
}
