export const updateStaff = createAsyncThunk('appStaffs/updateStaff', async (staff, { dispatch }) => {
  await axios.patch('/api/v1/user/one', staff)
  await dispatch(getStaff(staff.id))
  await dispatch(getData(getState().staffs.params))
  return staff  
})

export const updateStaffs = createAsyncThunk('appStaffs/updateStaffs', async (params) => {
  const query = params.data.map(async (item) => {
    return await axios.patch('/api/v1/user/one', item)
  })
  await Promise.all(query)

  // await dispatch(getStaff(staff.id))
  // closeSwal()
  toastSuccess("Xóa thông tin nhân viên thành công")
  setTimeout(() => {
    window.location.reload()
  }, 500)
  // return staff  
})

export const appStaffsSlice = createSlice({
  name: 'appUsers',
  initialState: {
    data: [],
    total: 1,
    params: {},
    allData: [],
    selectedUser: null
  },
  reducers: {

  },
  extraReducers: builder => {
    builder
      .addCase(getAllData.fulfilled, (state, action) => {
        state.allData = action.payload
      })
      .addCase(getData.fulfilled, (state, action) => {
        state.data = action.payload.data
        state.params = action.payload.params
        state.total = action.payload.totalPages
      })
      .addCase(getStaff.fulfilled, (state, action) => {
        state.selectedUser = action.payload
      })
  }
})

export default appStaffsSlice.reducer