// ** Redux Imports
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'

// ** Axios Imports
// import axios from 'axios'
import { number } from 'prop-types'
import useJwt from '@src/auth/jwt/useJwt'
import { closeSwal, handleLoading } from '../../../sweetalert'
export const postData = createAsyncThunk('editDistribution/postData', async params => {
  try {
    handleLoading('Vui lòng chờ hệ thống...')
    const response = await useJwt.updateDistribution(params)
    await params.reloadTable()
    closeSwal()
    params.changeStateModal(true)
    return { nameDistribution: response.name, district: response.region, provinceCity: response.city, description: response.description, id: response.id }
  } catch (error) {
    console.log(error)
    closeSwal()
    params.changeStateModal(false)
    return null
  }
})

export const editDistributionSlice = createSlice({
  name: 'editDistribution',
  initialState: {
    id: number,
    nameDistribution: '',
    district: '',
    provinceCity: '',
    description: ''
  },
  reducers: {

  },
  extraReducers: builder => {
    builder.addCase(postData.fulfilled, (state, action) => {
      console.log(action.payload)
      state.id = action.payload.id
      state.nameDistribution = action.payload.nameDistribution
      state.district = action.payload.district
      state.provinceCity = action.payload.provinceCity
      state.description = action.payload.description
    })
  }
})

export default editDistributionSlice.reducer
