// ** Redux Imports
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'

// ** Axios Imports
// import axios from 'axios'
import useJwt from '@src/auth/jwt/useJwt'
import { closeSwal, handleLoading } from '../../../sweetalert'
export const postData = createAsyncThunk('addDistribution/postData', async params => {
  try {
    handleLoading("Vui lòng chờ hệ thống...")
    const response = await useJwt.addDistribution(params)
    await params.reloadTable()
    closeSwal()
    params.changeStateModal(true)
    return { id: response.id, nameDistribution: response.nameDistribution, district: response.district, provinceCity: response.provinceCity, description: response.description }
  } catch (error) {
    console.log(error)
    closeSwal()
    params.changeStateModal(false)
    return { 
      id: '',
      nameDistribution: '',
      district: '',
      provinceCity: '',
      description: ''
    }
  }
})

export const addDistributionSlice = createSlice({
  name: 'addDistribution',
  initialState: {
    id: '',
    nameDistribution: '',
    district: '',
    provinceCity: '',
    description: ''
  },
  reducers: {
    setId: (state, action) => {
      state.id = action.payload.id
    },
    setNameDistribution: (state, action) => {
      state.id = action.payload.nameDistribution
    },
    setDistrict: (state, action) => {
      state.district = action.payload.district
    },
    setProvinceCity: (state, action) => {
      state.id = action.payload.provinceCity
    },
    setDescription: (state, action) => {
      state.id = action.payload.description
    }
  },
  extraReducers: builder => {
    builder.addCase(postData.fulfilled, (state, action) => {
      state.id = action.payload.id
      state.nameDistribution = action.payload.nameDistribution
      state.district = action.payload.district
      state.provinceCity = action.payload.provinceCity
      state.description = action.payload.description
    })
  }
})

export default addDistributionSlice.reducer
