import { createAsyncThunk, createSlice } from "@reduxjs/toolkit"
import useJwt from '@src/auth/jwt/useJwt'
import { closeSwal, handleLoading, handleWarning, toastSuccess } from "../../../sweetalert"

export const getData = createAsyncThunk('formSocial/getData', async () => {
  try {
    const response = await useJwt.getSocialLinks()
    let arr = {}
    response.data.map(item => {
      arr = {
        ...arr,
        [item.name]: {
          id: item.id,
          name: item.name,
          link: item.link,
          description: item.description
        }
      }
    })
    console.log(arr)
    return arr
    
  } catch (error) {
    
  }
})

export const updateSocialLink = createAsyncThunk('formSocial/update', async (params) => {
  // console.log(params)
  try {
    handleLoading('Vui lòng chờ hệ thống...')
    await useJwt.updateSocialLinks(params.vhn)
    await useJwt.updateSocialLinks(params.treehut)
    await useJwt.updateSocialLinks(params.facebook)
    await useJwt.updateSocialLinks(params.youtube)
    await useJwt.updateSocialLinks(params.hotline)
    await useJwt.updateSocialLinks(params.reward_description)
    closeSwal()
    toastSuccess("Cập nhật thành công")
  } catch (error) {
    closeSwal()
    handleWarning("Cảnh báo", "Chỉnh sửa social link không thành công")
  }
})

export const formSocialLink = createSlice({
  name: 'formSocial',
  initialState: {
    vhn: {
      id: '',
      name: '',
      link: '',
      description: ''
    },
    treehut: {
      id: '',
      name: '',
      link: '',
      description: ''
    },
    facebook: {
      id: '',
      name: '',
      link: '',
      description: ''
    },
    youtube: {
      id: '',
      name: '',
      link: '',
      description: ''
    },
    hotline: {
      id: '',
      name: '',
      link: '',
      description: ''
    },
    reward_description:{
      id: '',
      name: '',
      link: '',
      description: ''
    }
  },
  reducers: {
    setVHN: (state, action) => {
      return {
        ...state,
        vhn: {
          ...state.vhn,
          link: action.payload
        }
      }
    },
    setTreehut: (state, action) => {
      return {
        ...state,
        treehut: {
          ...state.treehut,
          link: action.payload
        }
      }
    },
    setFacebook: (state, action) => {
      return {
        ...state,
        facebook: {
          ...state.facebook,
          link: action.payload
        }
      }
    },
    setYoutube: (state, action) => {
      return {
        ...state,
        youtube: {
          ...state.youtube,
          link: action.payload
        }
      }
    },
    setHotline: (state, action) => {
      return {
        ...state,
        hotline: {
          ...state.hotline,
          link: action.payload
        }
      }
    },
    setRewardDescription: (state, action) => {
      return {
        ...state,
        reward_description: {
          ...state.reward_description,
          link: action.payload
        }
      }
    }
  },
  extraReducers: builder => {
    builder.addCase(getData.fulfilled, (state, action) => {
      return {
        ...state,
        ...action.payload
      }
    })
  }
})

export default formSocialLink.reducer

export const {setVHN, setFacebook, setHotline, setRewardDescription, setTreehut, setYoutube} = formSocialLink.actions