import { createAsyncThunk, createSlice } from "@reduxjs/toolkit"
import useJwt from '@src/auth/jwt/useJwt'

export const getUsers = createAsyncThunk('formAddAgent/getUsers', async () => {
  // console.log('getUsers')
  const response = await useJwt.getAllUsers()
  // console.log(response)
  return {data: response.data.data}
})

export const getDistributions = createAsyncThunk('formAddAgent/getDistributions', async () => {
  // console.log('getDistributions')
  const response = await useJwt.getListDistributionNoParams()
  // console.log(response)
  return {distributions: response.data.data}
})

export const formAddAgentSlice = createSlice({
  name: 'formAddAgent',
  initialState: {
    idAgent: '',
    nameAgent: null,
    addressAgent: null,
    phoneAgent: null,
    emailAgent: null,
    
    allOwners: [],
    idOwner: null,

    allDistributions: [],
    allChoiceDistributions: null,

    nameOwner: null,
    phoneOwner: null,
    addressOwner: null,
    emailOwner: null,
    passwordOwner: null,
    confirmPasswordOwner: null,
    
    params: ''
  },
  reducers: {
    setIdAgent: (state, action) => {
      state.idAgent = action.payload
    },
    setNameAgent: (state, action) => {
      state.nameAgent = action.payload
    },
    setAddressAgent: (state, action) => {
      state.addressAgent = action.payload
    },
    setPhoneAgent: (state, action) => {
      state.phoneAgent = action.payload
    },
    setEmailAgent: (state, action) => {
      state.emailAgent = action.payload
    },
    resetStore: (state, action) => {
      console.log(action.payload)
      return {
        ...state,
        idAgent: '',
        nameAgent: null,
        addressAgent: null,
        phoneAgent: null,
        emailAgent: null,
        
        allOwners: [],
        idOwner: null,
        nameOwner: null,
        addressOwner: null,
        phoneOwner: null,
        emailOwner: null,
        passwordOwner: null,
        confirmPasswordOwner: null,

        // allDistributions: [],
        allChoiceDistributions: null,

        params: ''
      }
    },
    setIdOwner: (state, action) => {
      state.idOwner = action.payload
    },
    setNameOwner: (state, action) => {
      state.nameOwner = action.payload
    },
    setPhoneOwner: (state, action) => {
      state.phoneOwner = action.payload
    },
    setAddressOwner: (state, action) => {
      state.addressOwner = action.payload
    },
    setEmailOwner: (state, action) => {
      state.emailOwner = action.payload
    },
    setPasswordOwner: (state, action) => {
      state.passwordOwner = action.payload
    },
    setConfirmPasswordOwner: (state, action) => {
      state.confirmPasswordOwner = action.payload
    },
    setAllChoiceDistributions: (state, action) => {
      state.allChoiceDistributions = action.payload
    }
  },
  extraReducers: builder => {
    builder.addCase(getUsers.fulfilled, (state, action) => {
      state.allOwners = action.payload.data
    })
    .addCase(getDistributions.fulfilled, (state, action) => {
      console.log("action", action.payload.distributions)
      state.allDistributions = action.payload.distributions
    })
  }
})

export const addAgent = createAsyncThunk('formAddAgent/addAgent', async (params, {getState}) => {
  try {
    const state = getState().formAddAgent
    let autoIdAgent = ''
    if (state.idAgent === '') {
      let validIdAgent = false
      do {
        autoIdAgent = useJwt.generateID(6)
        validIdAgent = await useJwt.checkAgentID({idAgent: autoIdAgent})
      }
      while (!validIdAgent)
    }
    params = {
      idAgent: (state.idAgent === '') ? autoIdAgent : state.idAgent,
      nameAgent: state.nameAgent,
      addressAgent: state.addressAgent,
      phoneAgent: state.phoneAgent,
      emailAgent: state.emailAgent,
      idOwner: state.idOwner.value,
      allChoiceDistributions: state.allChoiceDistributions
    }
    // console.log(params)
    await useJwt.addAgent(params)
    // console.log(response)
    return "success"
  } catch (error) {
    console.log(error.message)
    return "error"
  }
})

