  refreshToken() {
    return axios.post(this.jwtConfig.refreshEndpoint, {
      refreshToken: this.getRefreshToken()
    })
  }

  // Distribution
  async addDistribution(params) {
    const response = await axios.post(`${this.jwtConfig.addDistributionEndpoint}`, {
      name: params.nameDistribution,
      region: params.district,
      city: params.provinceCity,
      description: params.description
    })
    return response
  }

  async getListDistribution(params) {
    return axios.get(`${this.jwtConfig.getListDistributionsEndpoint}?search=${params.q}&skip=${(params.page - 1) * params.perPage}&limit=${params.perPage}&order_by=id%20DESC&region=&name=&city=&description=&is_deleted=false`)
  }

  async updateDistribution(params) {
    return axios.patch(`${this.jwtConfig.updateDistributionEndpoint}/${params.id}`, params.body)
  }

  async deleteDistribution(params) {
    return axios.delete(`${this.jwtConfig.deleteDistributionEndpoint}/${params.id}`)
  }

  async getListDistributionNoParams () {
    return axios.get(`${this.jwtConfig.getListDistributionsEndpoint}?search=&skip=0&limit=100000&order_by=id%20DESC&region=&name=&city=&description=&is_deleted=false`)
  }

  // Agency
  async addAgent(params) {
    const {
      idOwner, 
      idAgent, 
      nameAgent,
      addressAgent,
      phoneAgent,
      emailAgent,
      allChoiceDistributions
      } = params
    const formData = new FormData()
    formData.append('user_id', idOwner)
    formData.append('agency_id', idAgent)
    formData.append('name', nameAgent)
    formData.append('address', addressAgent)
    formData.append('phone', phoneAgent)
    formData.append('email', emailAgent)

    let url = `${this.jwtConfig.addAgencyEndpoint}?`
    allChoiceDistributions.map(item => {
      url += `distributor_channel_id=${item.value}&`
    })
    url = url.substring(0, url.length - 1)
    return axios({
      method: 'post',
      url,
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      data: formData
    })
  }

  async addAgentWithOwner(params) {
    const {
      // idOwner, 
      idAgent, 
      nameAgent,
      addressAgent,
      phoneAgent,
      emailAgent,
      allChoiceDistributions,
      nameOwner,
      addressOwner,
      phoneOwner,
      emailOwner,
      passwordOwner
      } = params
    const formData = new FormData()
    // formData.append('user_id', idOwner)
    formData.append('agency_id', idAgent)
    formData.append('name', nameAgent)
    formData.append('address', addressAgent)
    formData.append('phone', phoneAgent)
    formData.append('email', emailAgent)
    formData.append('user_name', nameOwner)
    formData.append('user_address', addressOwner)
    formData.append('user_phone', phoneOwner)
    formData.append('user_email', emailOwner)
    formData.append('user_password', passwordOwner)

    let url = `${this.jwtConfig.addAgencyWithOwnerEndpoint}?`
    allChoiceDistributions.map(item => {
      url += `distributor_channel_id=${item.value}&`
    })
    url = url.substring(0, url.length - 1)
    return axios({
      method: 'post',
      url,
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      data: formData
    })
  }

  async editAgent(params) {
    const {
      id,
      idOwner, 
      // idAgent, 
      nameAgent,
      addressAgent,
      phoneAgent,
      emailAgent,
      allChoiceDistributions
      } = params
    const formData = new FormData()
    formData.append('user_id', idOwner)
    // formData.append('agency_id', idAgent)
    formData.append('name', nameAgent)
    formData.append('address', addressAgent)
    formData.append('phone', phoneAgent)
    formData.append('email', emailAgent)

    let url = `${this.jwtConfig.editAgencyEndpoint}/${id}?`
    allChoiceDistributions.map(item => {
      url += `new_distributor_channel_id=${item.value}&`
    })
    url = url.substring(0, url.length - 1)
    return axios({
      method: 'patch',
      url,
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      data: formData
    })
  }

  generateID(length) {
    let result             = ''
    const characters       = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
    const charactersLength = characters.length
    for (let i = 0; i < length; i++) {
      result += characters.charAt(Math.floor(Math.random() * charactersLength))
    }
   return result
  }

  async checkAgentID(params) {
    try {
      // console.log(params.idAgent)
      const response = await axios.get(`${this.jwtConfig.checkIdAgencyEndpoint}?skip=0&limit=10&order_by=id%20DESC&agency_id=${params.idAgent}&is_deleted=false`)
      // console.log(response)
      const data = response.data.data
      return !(data.length > 0)
    } catch (error) {
      return false
    }
    
  }

