// ** Redux Imports
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'
import useJwt from '@src/auth/jwt/useJwt'
import { closeSwal, handleLoading, handleWarning, toastSuccess } from '../../../sweetalert'
// ** Axios Imports

export const getData = createAsyncThunk('tableAgencies/getListAgency', async params => {
  console.log(params)
  params.showLoading(true)
  const response = await useJwt.getListAgency(params)
  const result = response.data.data
  console.log(result)
  params.showLoading(false)
  return { allData: result, data: result, pageTotal: response.data.page_total, pageSize: response.data.page_size, page: response.data.page, params }
})

export const tableAgenciesSlice = createSlice({
  name: 'tableAgencies',
  initialState: {
    data: [],
    pageTotal: 1,
    pageSize: 1,
    page: 1,
    params: {},
    allData: [],
    isShowLoading: false
  },
  reducers: {
    setIsShowLoading: (state, action) => {
      state.isShowLoading = action.payload
    }
  },
  extraReducers: builder => {
    builder.addCase(getData.fulfilled, (state, action) => {
      console.log("builder")
      state.data = action.payload.data
      state.params = action.payload.params
      state.allData = action.payload.allData
      state.pageTotal = action.payload.pageTotal
      state.pageSize = action.payload.pageSize
      state.page = action.payload.page
    })
  }
})

export const deleteAgency = createAsyncThunk('tableAgencies/deleteAgency', async (params) => {
  try {
    handleLoading('Đang xóa đại lý...')
    await useJwt.deleteAgency(params)
  } catch (error) {
    handleWarning('Cảnh báo', 'Xóa đại lý không thành công. <br/>Vui lòng kiểm tra lại!')
  }
})

export const deleteAgencies = createAsyncThunk('tableAgencies/deleteAgencies', async (params) => {
  try {
    handleLoading('Vui lòng chờ hệ thống...')
    console.log("data", params.data)
    const query = params.data.map(async (item) => {
      await useJwt.deleteAgency({
        id: item.id
      })
    })
    await Promise.all(query)
    await params.reloadTable()
    closeSwal()
    toastSuccess("Đã xóa các đại lý")
  } catch (error) {
    closeSwal()
    handleWarning('Cảnh báo', 'Xóa đại lý không thành công. <br/>Vui lòng kiểm tra lại!')
  }
})


export const reloadTable = createAsyncThunk('tableAgencies/reloadTable', async (params, {getState}) => {
  const {getData} = params
  const state = getState().tableAgencies
  await getData(state.params)
})
export default tableAgenciesSlice.reducer

export const {setIsShowLoading} = tableAgenciesSlice.actions
